/**
 * The application's vocabulary, in every language it ships.
 *
 * Generated by `scripts/build-app-strings.mjs` from `Themes/Languages/*.xaml`.
 * Each file is the curated slice of that language file — navigation, document
 * types, actions, common words, dashboard and shell strings — keyed by the XAML
 * key it came from, so a page can ask for `Dg.Base` and get the application's
 * own word for a base rate rather than an approximation of it.
 *
 * The website does not translate the software. Where a concept already has a
 * name in the product, the product's name is the one that is used.
 */

import type { Locale } from "./locales";
import { DEFAULT_LOCALE } from "./locales";

import arAE from "./app-strings/ar-AE.json";
import bnBD from "./app-strings/bn-BD.json";
import deDE from "./app-strings/de-DE.json";
import enUS from "./app-strings/en-US.json";
import esES from "./app-strings/es-ES.json";
import frFR from "./app-strings/fr-FR.json";
import hiIN from "./app-strings/hi-IN.json";
import idID from "./app-strings/id-ID.json";
import jaJP from "./app-strings/ja-JP.json";
import koKR from "./app-strings/ko-KR.json";
import ptBR from "./app-strings/pt-BR.json";
import ruRU from "./app-strings/ru-RU.json";
import trTR from "./app-strings/tr-TR.json";
import urPK from "./app-strings/ur-PK.json";
import zhCN from "./app-strings/zh-CN.json";

export type AppKeyMap = Record<string, string>;

export const APP_STRINGS: Record<Locale, AppKeyMap> = {
  "en-US": enUS,
  "ar-AE": arAE,
  "bn-BD": bnBD,
  "de-DE": deDE,
  "es-ES": esES,
  "fr-FR": frFR,
  "hi-IN": hiIN,
  "id-ID": idID,
  "ja-JP": jaJP,
  "ko-KR": koKR,
  "pt-BR": ptBR,
  "ru-RU": ruRU,
  "tr-TR": trTR,
  "ur-PK": urPK,
  "zh-CN": zhCN,
};

/** How many application keys the site ships per language. */
export const APP_KEY_COUNT = Object.keys(APP_STRINGS[DEFAULT_LOCALE]).length;

/**
 * The application's own English for a XAML key — used when a page quotes the
 * interface and needs the label the user sees in an English build.
 */
export function appString(locale: Locale, key: string): string | null {
  return APP_STRINGS[locale]?.[key] ?? APP_STRINGS[DEFAULT_LOCALE]?.[key] ?? null;
}

/**
 * The XAML keys this site actually leans on, as a list, for the audit script.
 */
export function appKeys(): string[] {
  return Object.keys(APP_STRINGS[DEFAULT_LOCALE]).sort();
}
